        public ThreadLocalLoggerTests() {
            // Ensure Logger is initialized
            if (Logger.Instance != null) {
                try { Logger.Shutdown(); } catch { }
            }
            Logger.Init(
                level: LogLevel.Debug, 
                flushIntervalMs: 5000,
                tags: new Dictionary<string, string>{ {"namespace", "backend-team"},{"env", "testing"} },
                overload: global::Log.OverloadPolicy.Block,
                queueSize: 1,
                logBufferSize: 1024*4
            );
            output();
            Logger.SetLevel(LogLevel.Info); output();
            Logger.SetLevel(LogLevel.Warn); output();
            Logger.SetLevel(LogLevel.Error); output();
            Logger.SetLevel(LogLevel.Fatal); output();
            //
            {
                Thread worker = new Thread(()=>{
                    Console.WriteLine("Hello from worker thread.");
                    output();
                });
                worker.Start();   // 启动线程
                worker.Join();    // 等待线程执行完毕
            }
            Thread.Sleep(1000);
            GC.Collect();
            GC.WaitForPendingFinalizers();
            GC.Collect();
            Thread.Sleep(1000);
            // 模拟抢 stdout 锁失败
            global::Log.Logger.StdoutOccupy = 1;
            Logger.SetLevel(LogLevel.Info); output();
            global::Log.Logger.StdoutOccupy = 0;
            Thread.Sleep(10000);
        }

        public void Dispose() {
            if (Logger.Instance != null) {
                try { Logger.Shutdown(); } catch { }
            }
        }

        [Fact]
        public void Current_ReturnsThreadLocalInstance() {
            var logger1 = ThreadLocalLogger.Current;
            var logger2 = ThreadLocalLogger.Current;

            Assert.NotNull(logger1);
            Assert.NotNull(logger2);
            Assert.Same(logger1, logger2);
        }

        [Fact]
        public void Current_DifferentThreads_ReturnsDifferentInstances() {
            ThreadLocalLogger? logger1 = null;
            ThreadLocalLogger? logger2 = null;

            var t1 = new Thread(() => { logger1 = ThreadLocalLogger.Current; });
            var t2 = new Thread(() => { logger2 = ThreadLocalLogger.Current; });

            t1.Start();
            t2.Start();
            t1.Join();
            t2.Join();

            Assert.NotNull(logger1);
            Assert.NotNull(logger2);
            Assert.NotSame(logger1, logger2);
        }

        [Fact]
        public void Lock_UnLock_WorksCorrectly() {
            var logger = ThreadLocalLogger.Current;

            logger.Lock();
            // Should be able to call unlock after lock
            logger.UnLock();

            // Should be able to lock again
            logger.Lock();
            logger.UnLock();
        }

        [Fact]
        public void Buffer_IsNotNull() {
            var logger = ThreadLocalLogger.Current;

            Assert.NotNull(logger.Buffer.Data);
            Assert.True(logger.Buffer.Data.Length > 0);
        }

        [Fact]
        public void Flush_DoesNotThrow_WhenBufferHasSpace() {
            var logger = ThreadLocalLogger.Current;

            logger.Lock();
            try {
                // Flush when buffer has space should not throw
                logger.Flush();
            }
            finally {
                logger.UnLock();
            }
        }

        [Fact]
        public void SwitchBuffer_WithEmptyBuffer_DoesNothing() {
            var logger = ThreadLocalLogger.Current;

            logger.Lock();
            try {
                // Ensure buffer is empty
                logger.Buffer.Length = 0;
                // SwitchBuffer with empty buffer should return early
                logger.SwitchBuffer();
            }
            finally {
                logger.UnLock();
            }
        }

        [Fact]
        public void SwitchBufferOnTime_WithEmptyBuffer_ReturnsTrue() {
            var logger = ThreadLocalLogger.Current;

            // Ensure buffer is empty
            logger.Lock();
            logger.Buffer.Length = 0;
            logger.UnLock();

            // SwitchBufferOnTime should handle empty buffer
            var result = logger.SwitchBufferOnTime();

            // Result depends on whether we could acquire lock and buffer state
            Assert.True(result || !result); // Just verify no exception
        }

        [Fact]
        public void SwitchBufferOnTime_WhenLocked_ReturnsFalse() {
            var logger = ThreadLocalLogger.Current;
            bool result = true;

            // Lock on main thread
            logger.Lock();

            // Try to switch from another thread while locked
            var t = new Thread(() => {
                result = logger.SwitchBufferOnTime();
            });
            t.Start();
            t.Join();

            logger.UnLock();

            Assert.False(result);
        }

        [Fact]
        public void MultipleThreads_WriteToSeparateBuffers() {
            var results = new bool[4];
            var threads = new Thread[4];

            for (int i = 0; i < 4; i++) {
                int idx = i;
                threads[i] = new Thread(() => {
                    var logger = ThreadLocalLogger.Current;
                    logger.Lock();
                    try {
                        logger.Buffer.Append($"thread-{idx}");
                        results[idx] = logger.Buffer.Length > 0;
                    }
                    finally {
                        logger.UnLock();
                    }
                });
            }

            foreach (var t in threads) t.Start();
            foreach (var t in threads) t.Join();

            Assert.All(results, r => Assert.True(r));
        }
    }
